import React, { useState } from 'react';
// import './AdminDashboard.css'; // We'll create this CSS file separately

const Dashboard = () => {
 

  const [contacts] = useState([
    { id: 1, name: 'Count Dracula', lastSeen: '2/28/2015', message: 'How have you been? I was...', avatar: 'dist/img/user1-128x128.jpg' },
    { id: 2, name: 'Sarah Doe', lastSeen: '2/23/2015', message: 'I will be waiting for...', avatar: 'dist/img/user7-128x128.jpg' },
    { id: 3, name: 'Nadia Jolie', lastSeen: '2/20/2015', message: 'I\'ll call you back at...', avatar: 'dist/img/user3-128x128.jpg' },
    { id: 4, name: 'Nora S. Vans', lastSeen: '2/10/2015', message: 'Where is your new...', avatar: 'dist/img/user5-128x128.jpg' },
    { id: 5, name: 'John K.', lastSeen: '1/27/2015', message: 'Can I take a look at...', avatar: 'dist/img/user6-128x128.jpg' },
    { id: 6, name: 'Kenneth M.', lastSeen: '1/4/2015', message: 'Never mind I found...', avatar: 'dist/img/user8-128x128.jpg' }
  ]);

  const [newMessage, setNewMessage] = useState('');
  const [newTodo, setNewTodo] = useState('');

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (newMessage.trim()) {
      const newMsg = {
        id: chatMessages.length + 1,
        name: 'You',
        message: newMessage,
        time: 'Now',
        side: 'right',
        avatar: 'dist/img/user3-128x128.jpg'
      };
      setChatMessages([...chatMessages, newMsg]);
      setNewMessage('');
    }
  };

  const handleAddTodo = () => {
    if (newTodo.trim()) {
      const newItem = {
        id: todoItems.length + 1,
        text: newTodo,
        done: false,
        time: 'Today',
        badgeColor: 'info'
      };
      setTodoItems([...todoItems, newItem]);
      setNewTodo('');
    }
  };

  const toggleTodo = (id) => {
    setTodoItems(todoItems.map(item => 
      item.id === id ? { ...item, done: !item.done } : item
    ));
  };

  const deleteTodo = (id) => {
    setTodoItems(todoItems.filter(item => item.id !== id));
  };

  const stats = [
    { value: '150', label: 'New Orders', color: 'info', icon: 'ion-bag' },
    { value: '53%', label: 'Bounce Rate', color: 'success', icon: 'ion-stats-bars' },
    { value: '44', label: 'User Registrations', color: 'warning', icon: 'ion-person-add' },
    { value: '65', label: 'Unique Visitors', color: 'danger', icon: 'ion-pie-graph' }
  ];

  return (
    <div>
      {/* Content Header */}
      <div>
        <div>
          <div className="row mb-2">
            <div className="col-sm-6">
              <h1 className="m-0">Dashboard</h1>
            </div>
            <div className="col-sm-6">
              <ol className="breadcrumb float-sm-right">
                <li className="breadcrumb-item"><a href="#">Home</a></li>
                <li className="breadcrumb-item active">Dashboard v1</li>
              </ol>
            </div>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <section className="content">
        <div className="container-fluid">
          {/* Stats Cards */}
          <div className="row">
            {stats.map((stat, index) => (
              <div key={index} className="col-lg-3 col-6">
                <div className={`small-box bg-${stat.color}`}>
                  <div className="inner">
                    <h3>{stat.value}</h3>
                    <p>{stat.label}</p>
                  </div>
                  <div className="icon">
                    <i className={`ion ${stat.icon}`}></i>
                  </div>
                  <a href="#" className="small-box-footer">
                    More info <i className="fas fa-arrow-circle-right"></i>
                  </a>
                </div>
              </div>
            ))}
          </div>

          {/* Main Row */}
        
        </div>
      </section>
    </div>
  );
};

export default Dashboard;
